import http from "node:http";
import { readFileSync, existsSync } from "node:fs";
import { join, extname } from "node:path";
import { fileURLToPath } from "node:url";
import { createStore } from "./store.js";

const PUBLIC = join(fileURLToPath(new URL("..", import.meta.url)), "public");
const TYPES = { ".html": "text/html; charset=utf-8", ".js": "text/javascript; charset=utf-8", ".css": "text/css; charset=utf-8" };

const normTag = (t) => (typeof t === "string" ? t.trim().toLowerCase() : null);
const validTag = (t) => t !== null && t.length >= 1 && t.length <= 20;
const today = () => new Date(Date.now() - new Date().getTimezoneOffset() * 60000).toISOString().slice(0, 10);
const validDue = (d) => typeof d === "string" && /^\d{4}-\d{2}-\d{2}$/.test(d) && new Date(d + "T00:00:00Z").toISOString().slice(0, 10) === d;

// Valida/normaliza tags e due do corpo; devolve { error } ou só os campos presentes.
function parseExtras(body) {
  const out = {};
  if (body.tags !== undefined) {
    if (!Array.isArray(body.tags)) return { error: "tags deve ser uma lista" };
    const tags = [...new Set(body.tags.map(normTag))];
    if (!tags.every(validTag)) return { error: "tag inválida (texto de 1 a 20 caracteres)" };
    if (tags.length > 5) return { error: "no máximo 5 tags" };
    out.tags = tags;
  }
  if (body.due !== undefined) {
    if (body.due !== null && !validDue(body.due)) return { error: "due deve ser uma data real AAAA-MM-DD" };
    out.due = body.due;
  }
  return out;
}

// Lê page/limit/tag/done/overdue; devolve { error } ou os valores.
function parseQuery(q) {
  const num = (k, def, max) => {
    const v = q.get(k);
    if (v === null) return def;
    return /^\d+$/.test(v) && Number(v) >= 1 && Number(v) <= max ? Number(v) : NaN;
  };
  const page = num("page", 1, Number.MAX_SAFE_INTEGER), limit = num("limit", 10, 50);
  if (Number.isNaN(page) || Number.isNaN(limit)) return { error: "page/limit inválidos" };
  const f = { page, limit };
  if (q.has("tag")) { f.tag = normTag(q.get("tag")); if (!validTag(f.tag)) return { error: "tag inválida" }; }
  if (q.has("done")) { if (!["true", "false"].includes(q.get("done"))) return { error: "done deve ser true ou false" }; f.done = q.get("done") === "true"; }
  if (q.has("overdue")) { if (q.get("overdue") !== "true") return { error: "overdue deve ser true" }; f.overdue = true; }
  return f;
}

export function createApp(store = createStore()) {
  const send = (res, status, body) => {
    if (status === 204) { res.writeHead(204); return res.end(); }
    res.writeHead(status, { "content-type": "application/json; charset=utf-8" });
    res.end(JSON.stringify(body));
  };
  const readBody = (req) => new Promise((resolve) => {
    let raw = ""; req.on("data", (c) => (raw += c));
    req.on("end", () => { try { resolve(raw ? JSON.parse(raw) : {}); } catch { resolve(null); } });
  });

  return http.createServer(async (req, res) => {
    const url = new URL(req.url, "http://localhost");
    const m = url.pathname.match(/^\/api\/tasks(?:\/(\d+))?$/);
    if (!m) {
      const file = join(PUBLIC, url.pathname === "/" ? "index.html" : url.pathname);
      if (!file.startsWith(PUBLIC) || !existsSync(file)) { res.writeHead(404); return res.end("Não encontrado"); }
      res.writeHead(200, { "content-type": TYPES[extname(file)] ?? "application/octet-stream" });
      return res.end(readFileSync(file));
    }
    const id = m[1] ? Number(m[1]) : null;

    if (req.method === "GET" && id === null) {
      const f = parseQuery(url.searchParams);
      if (f.error) return send(res, 400, { error: f.error });
      const now = today();
      const hit = store.all().filter((t) =>
        (f.tag === undefined || t.tags.includes(f.tag)) &&
        (f.done === undefined || t.done === f.done) &&
        (!f.overdue || (!t.done && t.due !== null && t.due < now)));
      return send(res, 200, { items: hit.slice((f.page - 1) * f.limit, f.page * f.limit), page: f.page, limit: f.limit, total: hit.length });
    }

    if (req.method === "POST" && id === null) {
      const body = await readBody(req);
      if (!body || typeof body.title !== "string" || !body.title.trim()) return send(res, 400, { error: "title é obrigatório" });
      if (body.title.trim().length > 100) return send(res, 400, { error: "title deve ter no máximo 100 caracteres" });
      const extras = parseExtras(body);
      if (extras.error) return send(res, 400, { error: extras.error });
      return send(res, 201, store.add({ title: body.title.trim(), ...extras }));
    }

    if (req.method === "PATCH" && id !== null) {
      const task = store.find(id);
      if (!task) return send(res, 404, { error: "tarefa não encontrada" });
      const body = await readBody(req);
      if (!body) return send(res, 400, { error: "JSON inválido" });
      if (typeof body.done === "boolean") task.done = body.done;
      return send(res, 200, task);
    }

    if (req.method === "DELETE" && id !== null) {
      return store.remove(id) ? send(res, 204) : send(res, 404, { error: "tarefa não encontrada" });
    }
    send(res, 405, { error: "método não permitido" });
  });
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  const port = Number(process.env.PORT || 3000);
  createApp().listen(port, () => console.log(`Tarefas em http://localhost:${port}`));
}

