const list = document.getElementById("list");
const form = document.getElementById("form");
const titleInput = document.getElementById("title");
const tagsInput = document.getElementById("tags");
const dueInput = document.getElementById("due");
const filterTag = document.getElementById("filter-tag");
const filterDone = document.getElementById("filter-done");
const prev = document.getElementById("prev");
const next = document.getElementById("next");
const pageInfo = document.getElementById("page-info");
const msg = document.getElementById("msg");
const LIMIT = 10;
let page = 1;

const today = () => new Date(Date.now() - new Date().getTimezoneOffset() * 60000).toISOString().slice(0, 10);
const api = (path, method = "GET", body) =>
  fetch(path, { method, headers: { "content-type": "application/json" }, body: body && JSON.stringify(body) });

async function load() {
  const q = new URLSearchParams({ page, limit: LIMIT });
  if (filterTag.value.trim()) q.set("tag", filterTag.value.trim());
  if (filterDone.value) q.set("done", filterDone.value);
  const res = await api("/api/tasks?" + q);
  if (!res.ok) { msg.textContent = (await res.json()).error; return; }
  const data = await res.json();
  const pages = Math.max(1, Math.ceil(data.total / data.limit));
  if (page > pages) { page = pages; return load(); }
  msg.textContent = "";
  list.replaceChildren();
  const now = today();
  for (const t of data.items) {
    const late = !t.done && t.due && t.due < now;
    const li = document.createElement("li");
    if (t.done) li.className = "done";
    if (late) li.classList.add("overdue");
    const box = document.createElement("input");
    box.type = "checkbox"; box.checked = t.done;
    box.addEventListener("change", async () => { await api(`/api/tasks/${t.id}`, "PATCH", { done: box.checked }); load(); });
    const text = document.createElement("span");
    text.textContent = t.title;
    const meta = document.createElement("small");
    meta.textContent = [t.due && `📅 ${t.due}${late ? " (atrasada)" : ""}`, ...t.tags.map((x) => `#${x}`)].filter(Boolean).join(" ");
    const del = document.createElement("button");
    del.textContent = "Excluir";
    del.addEventListener("click", async () => { await api(`/api/tasks/${t.id}`, "DELETE"); load(); });
    li.append(box, text, meta, del);
    list.append(li);
  }
  pageInfo.textContent = `Página ${data.page} de ${pages} (${data.total})`;
  prev.disabled = data.page <= 1;
  next.disabled = data.page >= pages;
}

form.addEventListener("submit", async (e) => {
  e.preventDefault();
  const body = { title: titleInput.value, tags: tagsInput.value.split(",").filter((s) => s.trim()) };
  if (dueInput.value) body.due = dueInput.value;
  const res = await api("/api/tasks", "POST", body);
  if (!res.ok) { msg.textContent = (await res.json()).error; return; }
  titleInput.value = tagsInput.value = dueInput.value = "";
  load();
});
for (const el of [filterTag, filterDone]) el.addEventListener("input", () => { page = 1; load(); });
prev.addEventListener("click", () => { page--; load(); });
next.addEventListener("click", () => { page++; load(); });
load();

