cat >> test/api.test.js <<'EOF'

const post = (base, body) => json(base, "/api/tasks", "POST", body);
const get = (base, q) => json(base, "/api/tasks" + q);

test("normaliza tags e valida limites", () => withServer(async (base) => {
  const r = await post(base, { title: "x", tags: [" Casa ", "casa", "CASA", "Work"], due: "2030-02-28" });
  assert.deepEqual((await r.json()).tags, ["casa", "work"]);
  for (const tags of ["a", [1], ["  "], ["a".repeat(21)], ["1", "2", "3", "4", "5", "6"], null])
    assert.equal((await post(base, { title: "x", tags })).status, 400, JSON.stringify(tags));
  assert.equal((await post(base, { title: "x", tags: ["a", "A", "b", "c", "d", "e"] })).status, 201);
  for (const due of ["2030-02-30", "2030-2-3", "amanhã", 5, "2030-13-01"])
    assert.equal((await post(base, { title: "x", due })).status, 400, String(due));
  assert.equal((await post(base, { title: "x".repeat(101) })).status, 400);
  assert.equal((await post(base, { title: "x".repeat(100) })).status, 201);
}));

test("PATCH altera tags/due, due:null limpa, inválido não altera nada", () => withServer(async (base) => {
  const t = await (await post(base, { title: "x", due: "2030-01-01" })).json();
  const r = await (await json(base, `/api/tasks/${t.id}`, "PATCH", { tags: [" A "], due: null })).json();
  assert.deepEqual([r.tags, r.due], [["a"], null]);
  assert.equal((await json(base, `/api/tasks/${t.id}`, "PATCH", { tags: ["b"], due: "2030-02-31", done: true })).status, 400);
  const [cur] = (await (await get(base, "")).json()).items;
  assert.deepEqual([cur.tags, cur.done], [["a"], false]);
}));

test("paginação e filtros combinados", () => withServer(async (base) => {
  for (let i = 1; i <= 12; i++) await post(base, { title: `t${i}`, tags: i % 2 ? ["Impar"] : [], due: i <= 4 ? "2000-01-01" : "2999-01-01" });
  const p2 = await (await get(base, "?page=2")).json();
  assert.deepEqual([p2.items.length, p2.page, p2.limit, p2.total], [2, 2, 10, 12]);
  assert.ok(p2.items[0].id < p2.items[1].id);
  assert.equal((await (await get(base, "?limit=5&page=3")).json()).items.length, 2);
  assert.equal((await (await get(base, "?tag=IMPAR")).json()).total, 6);
  const first = (await (await get(base, "?limit=1")).json()).items[0];
  await json(base, `/api/tasks/${first.id}`, "PATCH", { done: true });
  assert.equal((await (await get(base, "?done=true")).json()).total, 1);
  assert.equal((await (await get(base, "?done=false")).json()).total, 11);
  assert.equal((await (await get(base, "?overdue=true")).json()).total, 3); // t1 feita não conta
  assert.equal((await (await get(base, "?overdue=true&tag=impar")).json()).total, 1); // só t3
  assert.equal((await (await get(base, "?page=99")).json()).items.length, 0);
}));

test("parâmetros de consulta inválidos => 400", () => withServer(async (base) => {
  for (const q of ["page=0", "page=x", "page=1.5", "limit=0", "limit=51", "limit=-1", "done=talvez", "overdue=false", "tag=", "tag=%20"])
    assert.equal((await get(base, "?" + q)).status, 400, q);
}));
EOF
cat >> README.md <<'EOF'

### Tarefas: tags, prazo e listagem (ticket #214)
- `title`: até 100 caracteres (após tirar espaços das pontas).
- `tags` (opcional, padrão `[]`): até 5 tags distintas. Cada uma é normalizada (espaços das pontas removidos, minúsculas, repetidas descartadas) e deve ter 1 a 20 caracteres; item que não seja texto, tag vazia/longa ou mais de 5 => 400.
- `due` (opcional, padrão `null`): data real `AAAA-MM-DD`; `null` no PATCH limpa a data.
- PATCH aceita `done`, `tags` e `due`; se algum for inválido responde 400 e nada é alterado.

`GET /api/tasks` responde `{ items, page, limit, total }` (ordem crescente de id; `total` já considera os filtros, que se combinam):

| Parâmetro | Descrição |
|---|---|
| `page` | inteiro ≥ 1 (padrão 1) |
| `limit` | inteiro de 1 a 50 (padrão 10) |
